/* 校园社区扩展：所有身份、对话、地图与学时均为本地演示。 */
window.createCampusCommunity = function (ctx) {
  'use strict';
  const {state,school,esc,icon,heading,btn,footer,showModal,closeModal,navigate,renderPage,toast,ensureAuth}=ctx;
  const $=s=>document.querySelector(s);
  const key='xueyu-community-demo-v1';
  let stored={};
  try{stored=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}
  const arr=k=>Array.isArray(stored[k])?stored[k]:[];
  const data={posts:arr('posts'),likes:arr('likes'),replies:arr('replies'),messages:arr('messages'),read:arr('read'),enrollments:arr('enrollments'),claims:arr('claims'),blocked:arr('blocked')};
  // Carry existing公益活动报名 from the earlier demo into the volunteer module.
  let migrated=false;
  for(const campus of window.CAMPUS_DATA.schools){
    const event=campus.events.find(e=>e.category==='公益');
    const programId=campus.id+'-program-1';
    if(event&&state.joined.includes(event.id)&&!data.enrollments.some(e=>e.schoolId===campus.id&&e.programId===programId)){
      data.enrollments.push({id:campus.id+'-existing-vol-enrollment',schoolId:campus.id,programId,status:'已报名',date:'2026-10-24'});migrated=true;
    }
  }
  if(migrated){try{localStorage.setItem(key,JSON.stringify(data));}catch{}}
  const ui={forumFilter:'全部',forumQuery:'',sort:'latest',mapFilter:'全部',mapQuery:'',place:null,zoom:1,route:false,thread:null,contactQuery:'',ledgerFilter:'全部'};
  const save=()=>{try{localStorage.setItem(key,JSON.stringify(data));}catch{toast('浏览器存储空间不足，本次操作暂保留在当前页面。');}};
  const uid=type=>`${school().id}-${type}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
  const stamp=()=>new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});
  const categories=['全部','学习交流','校园生活','失物招领','树洞','志愿服务'];
  const smallNote=(text,i='shield')=>`<div class="community-note">${icon(i)}<span>${text}</span></div>`;
  const schoolPosts=()=>{
    const s=school(),q=s.id==='qinghe';
    const base=[
      {title:q?'图书馆三楼的窗边，真的很适合读书':'创新中心的小组讨论室怎么约？',body:q?'今天发现图书馆三楼西侧的窗边座位，下午有很漂亮的光。最近想找一个固定的自习搭子，周二和周四下午都有空，欢迎一起学习！':'准备做课程项目，想找一个有白板的小组讨论空间。有人用过创新中心的预约吗？想交流一下预约流程，也欢迎一起组队做小项目。',category:'学习交流',author:'苏同学',authorId:'study',anonymous:false,likes:24,replies:['三楼也很安静！记得提前查看预约时间。','可以先看看生活指南里的学习空间介绍。'],time:'今天 11:20'},
      {title:q?'收集到了，属于青禾的秋天':'今天的银杏步道，像电影里的画面',body:'散步时遇到一束很好看的光，突然觉得偶尔走慢一点也很好。大家最喜欢校园里的哪个角落？想把这些地方整理成一个周末散步清单。',category:'校园生活',author:'周同学',authorId:'music',anonymous:false,likes:38,replies:['湖边的长椅，适合傍晚发呆。'],time:'今天 10:45'},
      {title:'最近有点迷茫，想听听大家怎么安排自己的节奏',body:'有时候看到身边的人都很忙，就会忍不住想把每个空闲都填满。最近在尝试每天只给自己安排一件真正重要的事。你们会怎么平衡课业和自己的兴趣呢？',category:'树洞',author:null,authorId:null,anonymous:true,likes:19,replies:['慢一点也没关系，找到适合自己的节奏就好。','可以试着留一段完全不安排任务的时间。'],time:'今天 09:30'},
      {title:'拾到一本浅绿色笔记本，已交到服务大厅',body:'在公共教学楼附近捡到一本浅绿色封面的笔记本，已交给学生服务大厅工作人员。失主可以描述内页特征认领，评论里不要公开个人电话或学号。',category:'失物招领',author:'苏同学',authorId:'study',anonymous:false,likes:12,replies:[],time:'昨天 17:20'},
      {title:'第一次参加志愿活动，需要提前准备什么？',body:'准备参加这周的校园志愿活动，想了解签到、服务记录和学时申报的流程。志愿服务中心已经把活动和服务记录放到学屿里了，有一起参加的同学吗？',category:'志愿服务',author:'晓禾',authorId:'volunteer',anonymous:false,likes:16,replies:['可以在志愿中心查看活动说明，完成服务后提交学时申报。'],time:'昨天 15:00'}
    ].map((p,i)=>({...p,id:`${s.id}-post-${i+1}`,schoolId:s.id,mine:false,created:Date.parse('2026-10-23T12:00:00+08:00')-i*10000,seedReplies:p.replies.map((body,j)=>({id:`${s.id}-seed-reply-${i}-${j}`,body,author:j?'陈同学':'校园同学',anonymous:false,time:'今天'}))}));
    return [...data.posts.filter(p=>p.schoolId===s.id),...base];
  };
  const findPost=id=>schoolPosts().find(p=>p.id===id);
  const repliesFor=p=>[...(p.seedReplies||[]),...data.replies.filter(r=>r.postId===p.id&&r.schoolId===school().id)];
  const likeCount=p=>p.likes+(data.likes.includes(p.id)?1:0);
  const authorName=p=>p.anonymous?'匿名同学':p.author;
  function postCard(p){return `<article class="post-card"><div class="post-author"><span class="community-avatar ${p.anonymous?'anonymous':''}">${p.anonymous?icon('leaf'):esc((p.author||'同学')[0])}</span><div><strong>${esc(authorName(p))}${p.anonymous?'<span class="anon-badge">匿名</span>':''}${p.mine?'<span class="mine-badge">我发布的</span>':''}</strong><small>${esc(p.time)} · ${esc(school().shortName)}校内</small></div><span class="post-category">${esc(p.category)}</span></div><button class="post-open" data-action="community-post" data-id="${esc(p.id)}"><h3>${esc(p.title)}</h3><p>${esc(p.body)}</p></button><div class="post-actions"><button class="${data.likes.includes(p.id)?'liked':''}" data-action="community-like" data-id="${esc(p.id)}" aria-pressed="${data.likes.includes(p.id)}" aria-label="点赞：${esc(p.title)}">${icon('heart')}<span>${likeCount(p)}</span></button><button data-action="community-post" data-id="${esc(p.id)}">${icon('chat')}<span>${repliesFor(p).length} 条讨论</span></button>${!p.anonymous&&!p.mine?`<button class="post-private" data-action="community-chat-author" data-id="${esc(p.id)}">${icon('message')}私聊作者</button>`:`<small>${p.anonymous?'匿名展示，安心交流':'在校园里分享一点日常'}</small>`}</div></article>`;}
  function filteredPosts(){let ps=schoolPosts().filter(p=>(ui.forumFilter==='全部'||p.category===ui.forumFilter)&&`${p.title}${p.body}`.includes(ui.forumQuery));return ps.sort(ui.sort==='hot'?(a,b)=>likeCount(b)-likeCount(a):(a,b)=>b.created-a.created);}
  function feed(){const ps=filteredPosts();return ps.length?ps.map(postCard).join(''):`<div class="empty-state">${icon('chat')}<h3>这里还没有相关讨论</h3><p>换个关键词，或发一个新话题吧。</p></div>`;}
  function forumPage(){return `${heading('GOOD TO SEE YOU HERE','在校园，找到同频的人','校园里的想法、问题与小美好，都值得被听见。',btn(icon('plus')+'发布话题','community-compose'))}<div class="community-layout"><div><div class="forum-welcome"><span class="welcome-leaf">${icon('leaf')}</span><div><strong>欢迎来到${esc(school().shortName)}的校园会客厅</strong><p>可以实名分享，也可以选择匿名，说说此刻的心情。</p></div><span class="campus-only">仅本校</span></div><div class="filter-row"><div class="filters">${categories.map(f=>`<button class="filter-btn ${ui.forumFilter===f?'active':''}" data-action="community-filter" data-id="${f}" aria-pressed="${ui.forumFilter===f}">${f==='全部'?'全部话题':f}</button>`).join('')}</div><label class="inline-search">${icon('search')}<input id="forum-search" type="search" aria-label="搜索论坛" placeholder="搜索你关心的话题" value="${esc(ui.forumQuery)}"/></label></div><div class="feed-sort"><span>${filteredPosts().length} 个话题</span><div><button class="${ui.sort==='latest'?'selected':''}" data-action="community-sort" data-id="latest">最新</button><button class="${ui.sort==='hot'?'selected':''}" data-action="community-sort" data-id="hot">热门</button></div></div><div id="forum-feed" class="forum-feed">${feed()}</div></div><aside class="community-aside"><section class="card"><div class="section-head"><h2>此刻的校园</h2>${icon('sparkle')}</div><div class="topic-list">${['# 发现校园里的秋天','# 找到同频的学习搭子','# 第一次志愿服务','# 今天也有小确幸'].map((t,i)=>`<button data-action="community-topic" data-id="${i}"><span>${t}</span>${icon('chevron')}</button>`).join('')}</div></section><section class="forum-tip"><span class="eyebrow">A KINDER CAMPUS</span><h3>把善意，留在每一次对话里。</h3><p>分享经验，尊重不同。<br/>遇到有共鸣的想法，就留一句鼓励。</p><div class="mini-feature">${icon('shield')}匿名帖不展示姓名、学院与学号。</div></section>${smallNote('示例话题与本地发帖仅保存在此浏览器，尚未接通多人论坛。')}</aside></div>${footer()}`;}
  function compose(){showModal(`<div class="modal-content"><span class="modal-tag">${esc(school().name)} · 校园论坛</span><h2>分享一个校园里的想法。</h2><p class="modal-intro">一个问题、一段日常，或一个新的相遇。</p><form id="community-post-form"><label class="form-label" for="post-category">话题分类</label><select id="post-category" name="category" class="form-input">${categories.slice(1).map(c=>`<option>${c}</option>`).join('')}</select><label class="form-label" for="post-title">标题</label><input class="form-input" id="post-title" name="title" placeholder="用一句话说说你想分享的事" maxlength="80" required/><label class="form-label" for="post-body">内容</label><textarea id="post-body" name="body" class="form-input" rows="6" maxlength="2000" placeholder="分享具体经历，提问、解答，也尊重不同的声音…" required></textarea><label class="anonymous-option"><input type="checkbox" name="anonymous" id="post-anonymous"/><span>${icon('leaf')}匿名发布<small>帖子显示为“匿名同学”，不展示个人身份。</small></span></label><p class="form-note">这是本地论坛演示，帖子不会发布给真实同学。</p><button class="primary-btn full-btn" type="submit">发布话题 ${icon('arrow')}</button></form></div>`);}
  function showPost(id){const p=findPost(id);if(!p)return;showModal(`<div class="modal-content"><span class="modal-tag">${esc(p.category)} · ${esc(school().shortName)}校内</span><h2>${esc(p.title)}</h2><div class="post-author post-detail-author"><span class="community-avatar ${p.anonymous?'anonymous':''}">${p.anonymous?icon('leaf'):esc((p.author||'同学')[0])}</span><div><strong>${esc(authorName(p))}${p.anonymous?'<span class="anon-badge">匿名</span>':''}</strong><small>${esc(p.time)}</small></div>${!p.anonymous&&!p.mine?`<button class="text-link" data-action="community-chat-author" data-id="${id}">${icon('message')}私聊作者</button>`:''}</div><div class="detail-body post-full-body">${esc(p.body)}</div><div class="detail-actions"><button class="secondary-btn ${data.likes.includes(id)?'liked':''}" data-action="community-like" data-id="${id}" data-detail="true">${icon('heart')}${likeCount(p)} 次赞同</button><small>${p.anonymous?'作者身份未在帖子中展示':'本校校园话题'}</small></div><section class="reply-section"><h3>一起聊聊 · ${repliesFor(p).length}</h3><div class="replies">${repliesFor(p).length?repliesFor(p).map(r=>`<div class="reply"><span class="community-avatar ${r.anonymous?'anonymous':''}">${r.anonymous?icon('leaf'):esc((r.author||'同学')[0])}</span><div><strong>${r.anonymous?'匿名同学':esc(r.author)}<small>${esc(r.time)}</small></strong><p>${esc(r.body)}</p></div></div>`).join(''):'<p class="form-note">还没有回复，来接住这个话题吧。</p>'}</div><form id="community-reply-form" data-id="${id}"><label class="sr-only" for="reply-body">回复内容</label><textarea class="form-input" id="reply-body" name="body" rows="3" maxlength="1000" placeholder="分享你的想法…" required></textarea><div class="reply-form-bottom"><label class="checkbox-label"><input type="checkbox" name="anonymous"/>匿名回复</label><button class="primary-btn" type="submit">发送回复 ${icon('arrow')}</button></div></form></section></div>`,true);}
  function contacts(){const s=school();return [
    {id:`${s.id}-contact-study`,name:'苏同学',avatar:'苏',role:s.id==='qinghe'?'设计与创新学院 · 校内同学':'计算机与智能工程学院 · 校内同学',color:'green',intro:'你好呀，看到了你分享的学习计划，要不要一起找个时间自习？'},
    {id:`${s.id}-contact-music`,name:'周同学',avatar:'周',role:s.id==='qinghe'?'声浪音乐社 · 活动伙伴':'回声音乐社 · 活动伙伴',color:'peach',intro:'欢迎来音乐社玩！草坪活动的安排都在社团广场里，想了解什么可以聊聊。'},
    {id:`${s.id}-contact-volunteer`,name:'晓禾',avatar:'禾',role:'志愿服务中心 · 演示联系人',color:'purple',intro:'你好，我是志愿服务中心的演示联系人。报名、签到和学时申报都可以在志愿中心体验。'}
  ];}
  const findContact=id=>contacts().find(c=>c.id===id);
  function conversation(c){return [{id:c.id+'-seed-1',threadId:c.id,schoolId:school().id,direction:'in',body:c.intro,time:'今天 10:20',simulated:true},...data.messages.filter(m=>m.threadId===c.id&&m.schoolId===school().id)];}
  const unread=c=>!data.read.includes(c.id)&&!data.messages.some(m=>m.threadId===c.id)?1:0;
  function contactRows(){const cs=contacts().filter(c=>(c.name+c.role).includes(ui.contactQuery));return cs.length?cs.map(c=>{const last=conversation(c).at(-1);return `<button class="contact-row ${(ui.thread||contacts()[0].id)===c.id?'active':''}" data-action="community-thread" data-id="${c.id}"><span class="community-avatar ${c.color}">${c.avatar}</span><span class="contact-row-text"><strong>${c.name}<small>今天</small></strong><span>${esc(last.body)}</span></span>${unread(c)?'<i class="unread-dot"></i>':''}</button>`;}).join(''):'<p class="form-note" style="padding:20px">没有找到相关联系人。</p>';}
  function messagesPage(){const c=findContact(ui.thread)||contacts()[0],blocked=data.blocked.includes(c.id);return `${heading('A CONVERSATION STARTS HERE','校园私信','从一个话题，到一次轻松的对话。',btn(icon('plus')+'开始新对话','community-new-chat','secondary'))}<div class="chat-app ${ui.thread?'mobile-conversation':'mobile-contact-list'}"><aside class="contact-panel"><div class="contact-panel-head"><h3>我的对话</h3><span>${contacts().length}</span></div><label class="chat-contact-search">${icon('search')}<input id="contact-search" type="search" placeholder="搜索同学或组织" aria-label="搜索联系人" value="${esc(ui.contactQuery)}"/></label><div id="contact-list">${contactRows()}</div><div class="contact-panel-foot">${icon('shield')}仅展示当前学校的演示联系人</div></aside><section class="conversation-panel"><div class="conversation-header"><button class="icon-btn chat-back" data-action="community-chat-back" aria-label="返回会话列表">${icon('left')}</button><span class="community-avatar ${c.color}">${c.avatar}</span><div><h3>${c.name}</h3><p>${esc(c.role)}</p></div><button class="icon-btn" data-action="community-chat-menu" data-id="${c.id}" aria-label="会话设置">${icon('settings')}</button></div><div class="chat-local-notice">${icon('shield')}本地私聊演示 · 消息不会发送给真实用户</div><div class="chat-messages" id="chat-messages" aria-live="polite"><p class="chat-time-label">今天 · ${esc(school().name)}</p>${conversation(c).map(m=>`<div class="message-row ${m.direction==='out'?'outgoing':'incoming'}">${m.direction==='in'?`<span class="community-avatar small ${c.color}">${c.avatar}</span>`:''}<div><div class="message-bubble">${esc(m.body)}</div><div class="message-time">${esc(m.time)}${m.direction==='out'?' · 已保存到本地':m.simulated?' · 示例消息':''}</div></div>${m.direction==='out'?'<span class="community-avatar small">林</span>':''}</div>`).join('')}</div><form id="community-message-form" data-id="${c.id}" class="message-composer"><div class="composer-toolbar"><span>${blocked?'你已屏蔽该演示联系人':'聊聊校园里的大小事'}</span><button type="button" data-action="community-simulate-reply" data-id="${c.id}" ${blocked?'disabled':''}>${icon('sparkle')}模拟对方回复</button></div><label class="sr-only" for="message-body">私聊消息</label><textarea id="message-body" name="body" rows="3" maxlength="1000" placeholder="${blocked?'解除屏蔽后可以继续对话':'写点什么，开始一段对话…'}" ${blocked?'disabled':''} required></textarea><div class="composer-bottom"><small>Enter 发送 · Shift + Enter 换行</small><button class="primary-btn" type="submit" ${blocked?'disabled':''}>发送 ${icon('send')}</button></div></form></section></div>${footer()}`;}
  function openThread(id){const c=findContact(id);if(!c)return;ui.thread=c.id;if(!data.read.includes(id))data.read.push(id);save();navigate('messages');scrollChat();}
  function scrollChat(){requestAnimationFrame(()=>{const el=$('#chat-messages');if(el)el.scrollTop=el.scrollHeight;});}
  function newChat(){showModal(`<div class="modal-content"><span class="modal-tag">${esc(school().name)}</span><h2>从一句“你好”开始。</h2><p class="modal-intro">选择一位校内演示联系人。匿名帖不提供作者私聊入口。</p>${contacts().map(c=>`<button class="school-option chat-picker" data-action="community-thread" data-id="${c.id}"><span class="community-avatar ${c.color}">${c.avatar}</span><span><strong>${c.name}</strong><small>${esc(c.role)}</small></span>${icon('chevron')}</button>`).join('')}<p class="form-note">演示消息只保存在本浏览器，不向任何真实用户发送。</p></div>`);}
  function places(){const s=school(),q=s.id==='qinghe';return [
    {id:'library',name:q?'青禾图书馆':'求知图书馆',category:'学习',x:280,y:170,icon:'book',hours:'07:30–23:00',desc:'窗边的阅读位、安静自习区与小组学习空间，都在这里。',tags:['自习座位','图书借阅','小组讨论'],walk:8},
    {id:'teaching',name:q?'设计与创新学院':'计算机教学楼',category:'学习',x:560,y:155,icon:'graduation',hours:'07:00–22:00',desc:q?'上课、创作与工作坊的日常发生地。':'课程教室、计算机实验室与项目交流空间。',tags:['上课教室','课程实验','作品交流'],walk:7},
    {id:'club',name:'学生活动中心',category:'生活',x:790,y:170,icon:'people',hours:'09:00–21:30',desc:'社团排练、校园放映与活动报名的线下集合地。',tags:['社团活动','排练空间','多功能厅'],walk:12},
    {id:'dorm',name:q?'北苑宿舍区':'银杏学生公寓',category:'生活',x:130,y:350,icon:'home',hours:'生活区全天开放',desc:'宿舍、快递点和便利服务集中在这里。',tags:['宿舍生活','校园驿站','便民服务'],walk:11},
    {id:'volunteer',name:'志愿服务驿站',category:'办事',x:520,y:345,icon:'heart',hours:'工作日 09:00–17:00',desc:'了解志愿项目、参加服务说明会、咨询服务记录与学时申报。',tags:['志愿活动','学时咨询','公益交流'],walk:5},
    {id:'sports',name:q?'东区运动场':'西区田径场',category:'运动',x:790,y:390,icon:'run',hours:'06:30–22:00',desc:'把课业之外的时间留给跑步、球类和运动伙伴。',tags:['田径跑道','球类运动','校园慢跑'],walk:10},
    {id:'dining',name:q?'青禾小食堂':'知味学生食堂',category:'生活',x:280,y:475,icon:'coffee',hours:'06:30–21:00',desc:'早餐、午餐和晚饭后的那一点小满足。',tags:['学生食堂','校园咖啡','休息区'],walk:6},
    {id:'service',name:'学生服务大厅',category:'办事',x:555,y:505,icon:'school',hours:'工作日 09:00–16:30',desc:'校园卡、学生证明、失物认领等服务的线下入口。',tags:['校园卡','证明材料','失物认领'],walk:3}
  ];}
  function campusSVG(){const ps=places();const trees=[[75,110],[125,95],[175,115],[365,105],[395,125],[680,90],[860,95],[905,200],[910,360],[900,470],[760,530],[690,575],[90,530],[170,560],[380,590],[60,240],[390,220],[650,220],[350,355],[680,430],[90,440],[705,300]];return `<svg class="campus-svg" viewBox="0 0 1000 650" role="img" aria-label="${esc(school().name)}卡通校园示意图"><defs><pattern id="map-grain" width="25" height="25" patternUnits="userSpaceOnUse"><circle cx="3" cy="3" r=".65" fill="#b0bf97" opacity=".25"/></pattern><g id="map-tree"><ellipse cy="22" rx="18" ry="8" fill="#b6c795" opacity=".4"/><path d="M0 5v24" stroke="#9b9e6a" stroke-width="4" stroke-linecap="round"/><circle cy="-5" r="18" fill="#8ca978"/><circle cx="-9" cy="3" r="13" fill="#91af7a"/><circle cx="10" cy="2" r="13" fill="#7e9d6d"/></g></defs><rect width="1000" height="650" rx="24" fill="#f0f2df"/><rect width="1000" height="650" fill="url(#map-grain)"/><path d="M40 280C190 255 260 300 420 285S750 270 965 300M495 52C485 180 515 260 492 420S510 560 500 620" fill="none" stroke="#d6d8bf" stroke-width="30" stroke-linecap="round"/><path d="M40 280C190 255 260 300 420 285S750 270 965 300M495 52C485 180 515 260 492 420S510 560 500 620" fill="none" stroke="#fffaf0" stroke-width="22" stroke-linecap="round"/><path d="M280 185V287m280-120v120m230-100v104M130 345v-65m390 70h-25m295 25v-85M280 470V290m275 210h-60" stroke="#fffaf0" stroke-width="15" fill="none"/><path d="M240 355c45-55 130-40 143 18s-70 84-105 59-65-45-38-77Z" fill="#c5ded1"/><path d="M262 369c24-13 49-17 77-6m-65 33c16 7 32 6 48-1" stroke="#e2eee2" stroke-width="3" fill="none" stroke-linecap="round"/><text x="298" y="416" text-anchor="middle" font-size="12" fill="#88a897" font-family="sans-serif">${school().id==='qinghe'?'青禾小湖':'知行湖'}</text><rect x="695" y="327" width="191" height="121" rx="54" fill="#d7b99d"/><rect x="708" y="338" width="165" height="98" rx="45" fill="none" stroke="#f4e1cb" stroke-width="2"/><rect x="718" y="348" width="145" height="78" rx="36" fill="#b0c58c"/><rect x="747" y="350" width="86" height="73" fill="none" stroke="#e4ecd3" stroke-width="2"/><circle cx="790" cy="387" r="16" fill="none" stroke="#e4ecd3" stroke-width="2"/>${ps.filter(p=>p.id!=='sports').map((p,i)=>{const roof=['#789675','#bba884','#94a8b0','#a3b48b','#ba9c84','#abaf91','#819d83'][i%7];return `<g transform="translate(${p.x-48} ${p.y-20})"><ellipse cx="54" cy="47" rx="57" ry="15" fill="#c3ccb0" opacity=".35"/><path d="M0 0 76-15 108 3 32 20Z" fill="${roof}"/><path d="M0 0v41l32 19V20Z" fill="#d8d5ba"/><path d="M32 20 108 3v41L32 60Z" fill="#faf6e5"/><path d="m44 28 10-2v11l-10 2Zm22-5 10-2v11l-10 2Zm22-5 10-2v11l-10 2ZM10 15l9 5v10l-9-5Zm34 31 10-2v10l-10 2Zm22-5 10-2v10l-10 2Zm22-5 10-2v10l-10 2Z" fill="#9eb3a0"/></g>`;}).join('')}${trees.map(([x,y])=>`<use href="#map-tree" transform="translate(${x} ${y})"/>`).join('')}<path d="M448 605v-28h99v28M458 577v-10h79v10" fill="#e0d6b9" stroke="#bbb795" stroke-width="2"/><text x="497" y="598" text-anchor="middle" font-size="12" fill="#7d8971" font-family="sans-serif">校园南门</text><g transform="translate(935 60)"><path d="m0-20 9 32-9-6-9 6Z" fill="#81956c"/><text y="-28" text-anchor="middle" font-size="10" fill="#8a987a">N</text></g>${ui.route&&ui.place?routeSVG():''}</svg>`;}
  function routeSVG(){const p=places().find(p=>p.id===ui.place);if(!p)return '';return `<polyline points="500,590 500,290 ${p.x},290 ${p.x},${p.y+32}" fill="none" stroke="#d39454" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="9 7"/><circle cx="500" cy="590" r="8" fill="#d39454" stroke="white" stroke-width="3"/>`;}
  function filteredPlaces(){return places().filter(p=>(ui.mapFilter==='全部'||p.category===ui.mapFilter)&&(p.name+p.desc+p.tags.join('')).includes(ui.mapQuery));}
  function placeDetail(p){return `<span class="place-category">${esc(p.category)}空间</span><h2>${esc(p.name)}</h2><p>${esc(p.desc)}</p><div class="place-tags">${p.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="place-info">${icon('clock')}<span>${esc(p.hours)}<small>开放时间为演示设定</small></span></div><div class="place-info">${icon('run')}<span>从校园南门步行约 ${p.walk} 分钟<small>示意路线 · 非实时导航</small></span></div><button class="primary-btn full-btn" data-action="community-map-route" data-id="${p.id}">${icon('route')}${ui.route?'收起示意路线':'查看示意路线'}</button>${p.id==='volunteer'?'<button class="secondary-btn full-btn" style="margin-top:9px" data-route="volunteer">去志愿中心 '+icon('arrow')+'</button>':'<button class="text-link" style="margin:14px auto 0" data-route="guides">查看校园生活指南 '+icon('arrow')+'</button>'}`;}
  function mapPage(){const ps=filteredPlaces(),p=places().find(p=>p.id===ui.place);return `${heading('A LITTLE ADVENTURE ON CAMPUS','校园地图，换个角度逛逛。','卡通里的每一个角落，都是校园生活的一部分。',`<span class="campus-only">${icon('pin')}${esc(school().name)} · 示意地图</span>`)}<div class="filter-row"><div class="filters">${['全部','学习','生活','运动','办事'].map(f=>`<button class="filter-btn ${ui.mapFilter===f?'active':''}" data-action="community-map-filter" data-id="${f}">${f==='全部'?'全部地点':f}</button>`).join('')}</div><label class="inline-search">${icon('search')}<input id="map-search" type="search" aria-label="搜索校园地点" placeholder="图书馆、食堂、运动场…" value="${esc(ui.mapQuery)}"/></label></div><div class="map-layout"><div class="map-board"><div class="map-board-heading"><span>${icon('leaf')} ${esc(school().shortName)}漫游地图</span><small>点击建筑标记，发现校园角落</small></div><div class="map-stage"><div class="map-scene" style="width:${ui.zoom*100}%">${campusSVG()}${ps.map(p=>`<button class="map-pin ${ui.place===p.id?'active':''}" style="left:${p.x/10}%;top:${p.y/6.5}%" data-action="community-place" data-id="${p.id}" aria-label="地图地点：${esc(p.name)}" aria-pressed="${ui.place===p.id}"><span>${icon(p.icon)}</span><strong>${esc(p.name)}</strong></button>`).join('')}</div></div><div class="map-board-footer"><span>${ui.route&&p?`南门 → ${esc(p.name)} · 约 ${p.walk} 分钟（示意）`:'校园建筑、道路与距离均为虚构示意'}</span><div class="map-controls"><button data-action="community-zoom-out" aria-label="缩小地图">−</button><span>${Math.round(ui.zoom*100)}%</span><button data-action="community-zoom-in" aria-label="放大地图">+</button><button data-action="community-map-reset" aria-label="重置地图">${icon('compass')}</button></div></div></div><aside class="map-detail card">${p?placeDetail(p):`<div class="map-detail-intro"><span class="quick-icon">${icon('compass')}</span><h2>下一站，去哪儿？</h2><p>点击地图上的地点，查看开放时间、空间用途与步行示意路线。</p></div>`}<div class="place-list"><h3>${ui.mapQuery?'搜索结果':'校园地点'}</h3>${ps.length?ps.map(p=>`<button data-action="community-place" data-id="${p.id}" class="${ui.place===p.id?'selected':''}"><span class="place-list-icon">${icon(p.icon)}</span><span>${esc(p.name)}<small>${esc(p.category)} · 步行约${p.walk}分钟</small></span>${icon('chevron')}</button>`).join(''):'<p class="form-note">没有找到地点，换个关键词试试。</p>'}</div></aside></div>${footer()}`;}
  function programs(){const s=school(),event=s.events.find(e=>e.category==='公益');return [
    {id:`${s.id}-program-1`,eventId:event?.id,title:event?.title||'校园公益日',organization:event?.club||'校园志愿者协会',date:event?.date||'10月28日 周三',time:event?.time||'14:00–16:00',location:event?.location||'学生活动中心',hours:2,cover:event?.cover||'assets/event-outdoor.svg',description:'一起参加校园公益活动。完成服务后，提交服务说明，由组织方核验学时。报名本身不产生有效学时。'},
    {id:`${s.id}-program-2`,eventId:null,title:'图书馆整理伙伴计划',organization:s.id==='qinghe'?'青禾图书馆志愿队':'求知图书馆志愿队',date:'10月26日 周一',time:'15:00–17:00',location:s.id==='qinghe'?'青禾图书馆二层':'求知图书馆二层',hours:2,cover:'assets/event-film.svg',description:'协助整理书架、引导读者、维护公共学习空间。首次参加会安排服务说明，具体学时以组织方核验为准。'}
  ];}
  const enrollment=p=>data.enrollments.find(e=>e.programId===p.id&&e.schoolId===school().id);
  const findProgram=id=>programs().find(p=>p.id===id);
  function ledger(){const s=school();return [
    {id:s.id+'-vol-record-1',title:'新生报到引导服务',organization:'校青年志愿者协会',date:'2026-09-06',hours:6,status:'已确认',proof:'迎新现场引导与咨询，组织方确认（演示记录）。'},
    {id:s.id+'-vol-record-2',title:'校园环保与旧物整理',organization:'校园公益行动小组',date:'2026-09-21',hours:4,status:'已确认',proof:'校园公共空间整理与环保宣传，组织方确认（演示记录）。'},
    {id:s.id+'-vol-record-3',title:s.id==='qinghe'?'青禾阅读陪伴计划':'社区阅读陪伴计划',organization:'图书馆志愿服务队',date:'2026-10-12',hours:2.5,status:'已确认',proof:'阅读活动引导与场地整理，组织方确认（演示记录）。'},
    {id:s.id+'-vol-record-4',title:'社区周末公益服务',organization:'微光公益服务队',date:'2026-10-18',hours:3,status:'待审核',proof:'已提交服务说明，等待组织方审核（演示记录）。'},
    ...data.claims.filter(c=>c.schoolId===s.id),
    ...data.enrollments.filter(e=>e.schoolId===s.id&&!data.claims.some(c=>c.programId===e.programId&&c.schoolId===s.id)).map(e=>{const p=findProgram(e.programId);return p?{id:e.id,programId:p.id,title:p.title,organization:p.organization,date:e.date,hours:p.hours,status:e.status,proof:e.status==='已报名'?'报名已记录；完成服务并经审核后才能计入有效学时。':e.status==='服务中'?'已完成演示签到，服务结束后请签退。':'演示签到与签退已完成，可以提交学时申报。'}:null;}).filter(Boolean)
  ];}
  function hoursSummary(){const rows=ledger();return {confirmed:rows.filter(r=>r.status==='已确认').reduce((a,r)=>a+Number(r.hours),0),pending:rows.filter(r=>r.status==='待审核').reduce((a,r)=>a+Number(r.hours),0),count:rows.filter(r=>r.status==='已确认').length};}
  function statusClass(status){return status==='已确认'?'confirmed':status==='待审核'?'pending':status==='服务中'?'serving':'registered';}
  function ledgerRow(r){return `<article class="ledger-row"><span class="vol-record-icon ${statusClass(r.status)}">${icon(r.status==='已确认'?'check':'clock')}</span><div class="ledger-record"><h3>${esc(r.title)}</h3><p>${esc(r.organization)} · ${esc(r.date)}</p><small>${esc(r.proof)}</small></div><div class="ledger-hours"><strong>${r.hours}<small> h</small></strong><span class="status-badge ${statusClass(r.status)}">${r.status}</span></div>${r.programId&&r.status==='已报名'?`<button class="secondary-btn" data-action="community-checkin" data-id="${r.programId}">体验签到</button>`:r.programId&&r.status==='服务中'?`<button class="secondary-btn" data-action="community-checkout" data-id="${r.programId}">体验签退</button>`:r.programId&&r.status==='待申报'?`<button class="primary-btn" data-action="community-claim" data-id="${r.programId}">申报学时</button>`:''}</article>`;}
  function volunteerPage(){const h=hoursSummary(),rows=ledger().filter(r=>ui.ledgerFilter==='全部'||r.status===ui.ledgerFilter);return `${heading('SMALL ACTS, LASTING IMPACT','把善意，积成光。','校园志愿服务与成长记录，在这里慢慢累积。',btn(icon('plus')+'学时申报','community-claim'))}<div class="volunteer-hero"><div><span class="eyebrow">MY VOLUNTEER JOURNEY</span><h2>每一份付出，都值得被记录。</h2><p>${esc(school().name)} · 2026 秋季学期 · 演示记录</p><div class="vol-hero-links"><button data-action="community-vol-rules">${icon('shield')}学时如何确认？</button><button data-action="community-export">${icon('download')}导出服务记录</button></div></div><div class="vol-hero-art" aria-hidden="true"><span>♡</span><i>✦</i><b>✳</b></div></div><div class="vol-stats"><div><span>已确认服务学时</span><strong>${h.confirmed}<small>小时</small></strong><p>${h.count} 次服务记录 · 示例</p></div><div><span>认真参与的服务</span><strong>${h.count}<small>次</small></strong><p>按自己的节奏参与，让每次付出有迹可循</p></div><div><span>等待组织方审核</span><strong>${h.pending}<small>小时</small></strong><p>审核通过后再计入有效学时</p></div></div><div class="vol-flow">${[['people','报名活动'],['pin','完成签到'],['check','服务签退'],['file','提交申报'],['shield','组织确认']].map(([i,t],j)=>`<span>${icon(i)}${t}</span>${j<4?icon('chevron'):''}`).join('')}</div><section class="vol-project-section">${heading('DO SOMETHING GOOD','下一次，一起出发。','找到适合自己的公益活动。')}<div class="vol-program-grid">${programs().map(p=>{const en=enrollment(p),claimed=data.claims.some(c=>c.programId===p.id&&c.schoolId===school().id);return `<article class="vol-program-card"><img src="${esc(p.cover)}" alt="公益活动示意插画"/><div><span class="vol-hours-tag">预计 ${p.hours} 小时 · 以核验为准</span><h3>${esc(p.title)}</h3><p>${icon('clock')}${esc(p.date)} · ${esc(p.time)}</p><p>${icon('pin')}${esc(p.location)}</p><div class="vol-program-bottom"><small>${esc(p.organization)}</small><button class="${en?'secondary':'primary'}-btn" data-action="community-program" data-id="${p.id}">${claimed?'查看申报':en?'查看服务进度':'了解并报名'}${icon('arrow')}</button></div></div></article>`;}).join('')}</div></section><section class="vol-record-section"><div class="section-head"><div class="section-title"><h2>我的服务记录</h2><small>认真记下每一份付出</small></div><button class="text-link" data-action="community-export">导出 ${icon('download')}</button></div><div class="filters ledger-filters">${['全部','已确认','待审核','已报名','服务中','待申报'].map(f=>`<button class="filter-btn ${ui.ledgerFilter===f?'active':''}" data-action="community-ledger-filter" data-id="${f}">${f}</button>`).join('')}</div><div class="vol-ledger">${rows.length?rows.map(ledgerRow).join(''):'<div class="empty-state"><h3>这里还没有对应的服务记录</h3><p>参加一次志愿活动，让善意从这里开始。</p></div>'}</div></section>${smallNote('学时、审核状态与签到均为本地演示。正式有效学时须由学校或授权组织核验，学生申报不会直接增加已确认学时。')}${footer()}`;}
  function showProgram(id){const p=findProgram(id);if(!p)return;const en=enrollment(p),claim=data.claims.find(c=>c.programId===id&&c.schoolId===school().id);showModal(`<img class="modal-cover" src="${esc(p.cover)}" alt="志愿活动插画"/><div class="modal-content"><span class="modal-tag">志愿服务 · 预计 ${p.hours} 小时</span><h2>${esc(p.title)}</h2><p class="modal-intro">${esc(p.organization)}</p><div class="event-details"><div class="event-detail-item">${icon('clock')}<div><small>${esc(p.date)}</small><strong>${esc(p.time)}</strong></div></div><div class="event-detail-item">${icon('pin')}<div><small>集合地点</small><strong>${esc(p.location)}</strong></div></div></div><p class="detail-body">${esc(p.description)}</p><div class="vol-state-strip"><span>当前状态</span><strong>${claim?'待审核':en?.status||'尚未报名'}</strong></div><div class="detail-actions"><small>模拟报名和签到，不产生真实学时</small>${claim?btn('查看服务记录','community-go-vol','secondary'):!en?btn(icon('plus')+'报名志愿服务','community-enroll','primary',`data-id="${id}"`):en.status==='已报名'?btn(icon('pin')+'体验签到','community-checkin','primary',`data-id="${id}"`):en.status==='服务中'?btn(icon('check')+'体验签退','community-checkout','primary',`data-id="${id}"`):btn('申报学时','community-claim','primary',`data-id="${id}"`)}</div></div>`);}
  function enrollProgram(id){const p=findProgram(id);if(!p||enrollment(p))return;data.enrollments.push({id:uid('enrollment'),programId:id,schoolId:school().id,status:'已报名',date:'2026-10-24'});if(p.eventId&&!state.joined.includes(p.eventId)){state.joined.push(p.eventId);ctx.persist();}save();renderPage();showProgram(id);toast('已报名，完成服务后可申报学时');}
  function showClaim(id){const p=id?findProgram(id):null,en=p?enrollment(p):null;if(p&&en?.status!=='待申报'){toast('请先完成演示签到与签退，再提交学时申报');return;}if(p&&data.claims.some(c=>c.schoolId===school().id&&c.programId===p.id)){toast('这项活动已经提交过学时申报');return;}showModal(`<div class="modal-content"><span class="modal-tag">志愿服务 · 学时申报</span><h2>记下一段认真付出的时间。</h2><p class="modal-intro">填写服务信息，提交后进入待审核记录。</p><form id="community-claim-form" data-program="${p?.id||''}"><label class="form-label" for="claim-title">活动名称</label><input id="claim-title" name="title" class="form-input" value="${esc(p?.title||'')}" placeholder="参加了什么志愿活动？" maxlength="80" ${p?'readonly':''} required/><div class="claim-form-grid"><div><label class="form-label" for="claim-date">服务日期</label><input id="claim-date" name="date" class="form-input" type="date" max="2026-10-24" value="2026-10-24" required/></div><div><label class="form-label" for="claim-hours">申报学时（小时）</label><input id="claim-hours" name="hours" class="form-input" type="number" min="0.5" max="${p?.hours||24}" step="0.5" value="${p?.hours||2}" required/></div></div><label class="form-label" for="claim-org">组织单位</label><input id="claim-org" name="organization" class="form-input" maxlength="80" value="${esc(p?.organization||'')}" placeholder="组织活动的校内单位或社团" ${p?'readonly':''} required/><label class="form-label" for="claim-proof">服务说明</label><textarea id="claim-proof" name="proof" class="form-input" rows="4" maxlength="800" placeholder="说明服务内容、起止时间及可供核验的记录。请使用示例信息体验。" required></textarea><p class="form-error" id="claim-error" role="alert"></p>${smallNote('提交后为“待审核”，不计入已确认学时。当前仅保存演示记录，不向校方发起真实申请。')}<button class="primary-btn full-btn" type="submit">提交学时申报 ${icon('arrow')}</button></form></div>`);}
  function profileSummary(){const h=hoursSummary();return `<div class="profile-community-grid"><button data-route="volunteer"><span class="quick-icon">${icon('heart')}</span><div><strong>${h.confirmed}<small> 小时</small></strong><span>已确认志愿学时 · 示例</span></div>${icon('chevron')}</button><button data-route="messages"><span class="quick-icon">${icon('message')}</span><div><strong>校园私信</strong><span>与同频的人聊聊</span></div>${icon('chevron')}</button></div><div class="profile-shortcuts">${[['map','map','卡通校园地图'],['forum','chat','校园论坛'],['volunteer','heart','志愿中心'],['schedule','calendar','我的课表'],['news','news','校园资讯'],['clubs','people','社团活动'],['guides','compass','生活指南']].map(([r,i,t])=>`<button data-route="${r}">${icon(i)}${t}${icon('chevron')}</button>`).join('')}</div>`;}
  function homeDiscovery(){return `<section class="campus-discover">${[['map','map','卡通校园地图','换个角度，逛逛校园'],['forum','chat','校园论坛','听见校园里的声音'],['messages','message','校园私信','从一句你好开始'],['volunteer','heart','志愿学时','让每份善意有迹可循']].map(([r,i,t,d])=>`<button data-route="${r}"><span class="discover-icon">${icon(i)}</span><span><strong>${t}</strong><small>${d}</small></span>${icon('chevron')}</button>`).join('')}</section>`;}
  const actions={
    'community-compose':()=>ensureAuth(compose),'community-post':showPost,
    'community-like':(id,el)=>{if(!findPost(id))return;const i=data.likes.indexOf(id);if(i<0)data.likes.push(id);else data.likes.splice(i,1);save();renderPage();if(el.dataset.detail)showPost(id);},
    'community-filter':id=>{ui.forumFilter=categories.includes(id)?id:'全部';renderPage();},
    'community-sort':id=>{ui.sort=id==='hot'?'hot':'latest';renderPage();},
    'community-topic':id=>{ui.forumQuery='';ui.forumFilter=['校园生活','学习交流','志愿服务','树洞'][Number(id)]||'全部';navigate('forum');},
    'community-chat-author':id=>{const p=findPost(id);if(!p||p.anonymous||p.mine||!p.authorId)return;ensureAuth(()=>{if(findPost(id)&&!findPost(id).anonymous)openThread(`${school().id}-contact-${p.authorId}`);});},
    'community-new-chat':()=>ensureAuth(newChat),'community-thread':id=>ensureAuth(()=>openThread(id)),
    'community-chat-back':()=>{ui.thread=null;renderPage();},
    'community-simulate-reply':id=>ensureAuth(()=>{if(!findContact(id)||data.blocked.includes(id))return;data.messages.push({id:uid('message'),schoolId:school().id,threadId:id,direction:'in',body:'这是一次模拟回复：收到啦！可以先在学屿里查看活动安排和地图，我们再一起确认时间。',time:stamp(),simulated:true});save();renderPage();scrollChat();}),
    'community-chat-menu':id=>{const c=findContact(id);if(!c)return;showModal(`<div class="modal-content"><h2>与${c.name}的会话</h2><p class="modal-intro">${esc(school().name)} · 本地演示联系人</p><p class="detail-body">${data.blocked.includes(id)?'已屏蔽该联系人。解除后可继续体验对话。':'屏蔽后将暂停本演示中的消息发送与模拟回复。'}</p><div class="detail-actions">${btn(data.blocked.includes(id)?'解除屏蔽':'屏蔽该联系人','community-block','secondary',`data-id="${id}"`)}</div></div>`);},
    'community-block':id=>{if(!findContact(id))return;const i=data.blocked.indexOf(id);if(i<0)data.blocked.push(id);else data.blocked.splice(i,1);save();closeModal();renderPage();toast(i<0?'已屏蔽演示联系人':'已解除屏蔽');},
    'community-place-search':id=>{if(!places().some(p=>p.id===id))return;ui.place=id;ui.route=false;navigate('map');},
    'community-place':id=>{if(!places().some(p=>p.id===id))return;ui.place=id;ui.route=false;renderPage();},
    'community-map-filter':id=>{ui.mapFilter=id;ui.place=null;ui.route=false;renderPage();},
    'community-map-route':id=>{if(!places().some(p=>p.id===id))return;ui.place=id;ui.route=!ui.route;renderPage();},
    'community-zoom-in':()=>{ui.zoom=Math.min(1.8,Math.round((ui.zoom+.2)*10)/10);renderPage();},
    'community-zoom-out':()=>{ui.zoom=Math.max(1,Math.round((ui.zoom-.2)*10)/10);renderPage();},
    'community-map-reset':()=>{ui.zoom=1;ui.place=null;ui.route=false;ui.mapFilter='全部';ui.mapQuery='';renderPage();},
    'community-program':showProgram,'community-enroll':id=>ensureAuth(()=>enrollProgram(id)),
    'community-checkin':id=>ensureAuth(()=>{const p=findProgram(id),en=p&&enrollment(p);if(!en||en.status!=='已报名')return;en.status='服务中';en.checkedIn=stamp();save();renderPage();showProgram(id);toast('演示签到成功，服务结束后请签退');}),
    'community-checkout':id=>ensureAuth(()=>{const p=findProgram(id),en=p&&enrollment(p);if(!en||en.status!=='服务中')return;en.status='待申报';en.checkedOut=stamp();save();renderPage();showProgram(id);toast('演示签退成功，可以填写服务说明并申报学时');}),
    'community-claim':id=>ensureAuth(()=>showClaim(id)),'community-go-vol':()=>navigate('volunteer'),
    'community-ledger-filter':id=>{ui.ledgerFilter=id;renderPage();},
    'community-vol-rules':()=>showModal(`<div class="modal-content"><span class="modal-tag">志愿服务 · 学时说明</span><h2>把真实的付出，认真记下来。</h2><ol class="guide-steps"><li>报名志愿活动，先确认服务内容与时间。</li><li>按组织要求签到、完成服务并签退。</li><li>提交学时与服务说明，进入待审核记录。</li><li>组织方核验后，已确认学时才会增加。</li></ol><p class="form-note">本版本为演示。已确认记录为示例数据；演示申报只进入待审核，学生端不提供自行确认学时的入口。</p></div>`),
    'community-export':()=>{const quote=v=>{let t=String(v??'');if(/^[=+@\-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};const rows=[['学校','活动','组织单位','服务日期','学时','状态','备注'],...ledger().map(r=>[school().name,r.title,r.organization,r.date,r.hours,r.status,'演示记录，非正式学时证明'])];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${school().name}-志愿服务演示记录.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出演示服务记录，非正式学时证明');}
  };
  function onSubmit(event){const form=event.target;
    if(form.id==='community-post-form'){event.preventDefault();const schoolId=school().id;const title=form.elements.title.value.trim(),body=form.elements.body.value.trim(),anonymous=form.elements.anonymous.checked,category=form.elements.category.value;if(!title||!body||!categories.includes(category))return;ensureAuth(()=>{if(school().id!==schoolId)return;const p={id:uid('post'),schoolId,title:title.slice(0,80),body:body.slice(0,2000),category,anonymous,author:anonymous?null:school().student.name,authorId:null,mine:true,created:Date.now(),time:'刚刚',likes:0,seedReplies:[]};data.posts.unshift(p);save();closeModal();ui.forumFilter='全部';ui.forumQuery='';navigate('forum');toast(anonymous?'已匿名发布，不展示个人身份':'话题已发布到本地校园论坛');});}
    if(form.id==='community-reply-form'){event.preventDefault();const id=form.dataset.id,p=findPost(id),schoolId=school().id,body=form.elements.body.value.trim(),anonymous=form.elements.anonymous.checked;if(!p||!body)return;ensureAuth(()=>{if(school().id!==schoolId||!findPost(id))return;data.replies.push({id:uid('reply'),schoolId,postId:id,body:body.slice(0,1000),anonymous,author:anonymous?null:school().student.name,time:'刚刚'});save();renderPage();showPost(id);toast('回复已保存到本地讨论');});}
    if(form.id==='community-message-form'){event.preventDefault();const threadId=form.dataset.id,schoolId=school().id,body=form.elements.body.value.trim();if(!body||!findContact(threadId)||data.blocked.includes(threadId))return;ensureAuth(()=>{if(school().id!==schoolId||!findContact(threadId)||data.blocked.includes(threadId))return;data.messages.push({id:uid('message'),schoolId,threadId,direction:'out',body:body.slice(0,1000),time:stamp()});if(!data.read.includes(threadId))data.read.push(threadId);save();closeModal();renderPage();scrollChat();});}
    if(form.id==='community-claim-form'){event.preventDefault();if(!ctx.isAuthenticated()){ensureAuth(()=>showClaim(form.dataset.program||null));return;}const programId=form.dataset.program||null,p=programId?findProgram(programId):null,title=form.elements.title.value.trim(),organization=form.elements.organization.value.trim(),proof=form.elements.proof.value.trim(),date=form.elements.date.value,hours=Number(form.elements.hours.value);let error='';if(!title||!organization||proof.length<10)error='请填写活动、组织单位，并提供至少 10 个字的服务说明。';else if(!Number.isFinite(hours)||hours<.5||hours>(p?.hours||24)||hours*2!==Math.floor(hours*2))error='请按 0.5 小时填写学时，并在活动预计时数范围内申报。';else if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>'2026-10-24')error='请选择不晚于演示日期 2026-10-24 的服务日期。';else if(programId&&(!p||enrollment(p)?.status!=='待申报'||data.claims.some(c=>c.programId===programId&&c.schoolId===school().id)))error='活动状态已变化，请回到志愿中心查看，避免重复申报。';if(error){$('#claim-error').textContent=error;return;}data.claims.unshift({id:uid('claim'),schoolId:school().id,programId,title:title.slice(0,80),organization:organization.slice(0,80),date,hours,status:'待审核',proof:proof.slice(0,800)});save();closeModal();ui.ledgerFilter='全部';navigate('volunteer');toast('学时申报已保存为待审核，已确认学时保持不变');}
  }
  function onInput(event){const el=event.target;if(el.id==='forum-search'){ui.forumQuery=el.value;$('#forum-feed').innerHTML=feed();const count=$('.feed-sort>span');if(count)count.textContent=filteredPosts().length+' 个话题';}if(el.id==='contact-search'){ui.contactQuery=el.value;$('#contact-list').innerHTML=contactRows();}if(el.id==='map-search'){ui.mapQuery=el.value;const start=el.selectionStart;renderPage();const input=$('#map-search');input?.focus();input?.setSelectionRange?.(start,start);}}
  function onKeyDown(event){if(event.target.id==='message-body'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();event.target.form.requestSubmit();}}
  function schoolChanged(){ui.thread=null;ui.place=null;ui.route=false;ui.zoom=1;ui.forumQuery='';ui.forumFilter='全部';ui.mapQuery='';ui.mapFilter='全部';ui.contactQuery='';ui.ledgerFilter='全部';}
  function enrollmentChanged(id,joined){const p=programs().find(p=>p.eventId===id);if(!p)return;if(joined&&!enrollment(p))data.enrollments.push({id:uid('enrollment'),schoolId:school().id,programId:p.id,date:'2026-10-24',status:'已报名'});if(!joined)data.enrollments=data.enrollments.filter(e=>e.programId!==p.id||e.schoolId!==school().id||e.status!=='已报名');save();}
  function canCancelEnrollment(id){const p=programs().find(p=>p.eventId===id),e=p&&enrollment(p);if(e&&e.status!=='已报名'){toast('这项活动已有服务记录，请前往志愿中心查看进度');return false;}return true;}
  function volunteerEventInfo(e){const p=programs().find(p=>p.eventId===e.id);return p?`<div class="event-vol-info">${icon('heart')}志愿服务 · 预计 ${p.hours} 小时<small>完成服务并经组织方核验后计入</small><button data-route="volunteer">查看志愿中心 ${icon('arrow')}</button></div>`:'';}
  function searchGroups(){return [['校园话题','chat',schoolPosts().map(p=>({id:p.id,name:p.title,desc:p.category+' · '+authorName(p),kind:'community-post'}))],['地图地点','map',places().map(p=>({id:p.id,name:p.name,desc:p.category+' · '+p.hours,kind:'community-place-search'}))],['志愿项目','heart',programs().map(p=>({id:p.id,name:p.title,desc:p.organization,kind:'community-program'}))]];}
  return {personalData:()=>({posts:schoolPosts().filter(p=>p.mine),hours:hoursSummary(),pending:ledger().filter(r=>r.status==='待审核')}),searchGroups,pages:{map:mapPage,forum:forumPage,messages:messagesPage,volunteer:volunteerPage},actions,onSubmit,onInput,onKeyDown,schoolChanged,enrollmentChanged,canCancelEnrollment,volunteerEventInfo,profileSummary,homeDiscovery};
};
